package com.lolfm.simulator;import com.lolfm.domain.Position;
public final class ProgressionEconomyResolver {private final ProgressionRewardResolver rewards=new ProgressionRewardResolver();public void resolve(GameState s,int time){if(!s.isProgressionEnabled()||s.isFinished())return;for(TeamSide side:TeamSide.values())resolveTeam(s,side,time);}private void resolveTeam(GameState s,TeamSide side,int t){TeamState team=s.getTeamState(side);PlayerState top=team.playerAt(Position.TOP),mid=team.playerAt(Position.MID),jg=team.playerAt(Position.JUNGLE),adc=team.playerAt(Position.ADC),sup=team.playerAt(Position.SUPPORT);if(eligible(s,side,top,t,false))rewards.awardExperience(top,ExperienceSource.LANE_ECONOMY,ProgressionRuleConfig.SOLO_LANE_XP_PER_TICK,t);if(eligible(s,side,mid,t,false))rewards.awardExperience(mid,ExperienceSource.LANE_ECONOMY,ProgressionRuleConfig.SOLO_LANE_XP_PER_TICK,t);if(eligible(s,side,jg,t,true)){rewards.awardExperience(jg,ExperienceSource.JUNGLE_ECONOMY,ProgressionRuleConfig.JUNGLE_XP_PER_TICK,t);s.getProgressionExecutionStats().jungle();}boolean a=eligible(s,side,adc,t,false),u=eligible(s,side,sup,t,false);if(a&&u){rewards.awardExperience(adc,ExperienceSource.BOT_SHARED_ECONOMY,ProgressionRuleConfig.BOT_SHARED_XP_PER_PLAYER_PER_TICK,t);rewards.awardExperience(sup,ExperienceSource.BOT_SHARED_ECONOMY,ProgressionRuleConfig.BOT_SHARED_XP_PER_PLAYER_PER_TICK,t);s.getProgressionExecutionStats().shared();}else if(a){rewards.awardExperience(adc,ExperienceSource.BOT_SOLO_ECONOMY,ProgressionRuleConfig.BOT_SOLO_XP_PER_TICK,t);s.getProgressionExecutionStats().adcSolo();}else if(u){rewards.awardExperience(sup,ExperienceSource.BOT_SOLO_ECONOMY,ProgressionRuleConfig.BOT_SOLO_XP_PER_TICK,t);s.getProgressionExecutionStats().supportSolo();}else s.getProgressionExecutionStats().absent();}boolean eligible(GameState s,TeamSide side,PlayerState p,int t,boolean jungle){if(!p.isAlive(t)){s.getProgressionExecutionStats().dead();return false;}if(!p.canFarmAt(t)){s.getProgressionExecutionStats().recovery();return false;}if(p.getActivityState().getActivityType()!=PlayerActivityType.DEFAULT_ROLE){s.getProgressionExecutionStats().activity();return false;}if(p.getPosition()==Position.MID&&t<p.getRoamActionState().getRoamFarmBlockedUntilSeconds()){s.getProgressionExecutionStats().activity();return false;}if(jungle&&t<s.jungleActionState(side).getJungleFarmBlockedUntilSeconds()){s.getProgressionExecutionStats().activity();return false;}return true;}}
